const $=s=>document.querySelector(s),config=window.SHIRO_CONFIG||{},KEY='shiro.tasks.v1',DRAFT='shiro.draft.v1';
let tasks=[],filter='all',query='',reverse=false,user=null,auth=null,editId=null,toastTimer,firebase;
const labels={todo:'未着手',doing:'進行中',done:'完了'},states=['todo','doing','done'];
try{tasks=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(tasks))tasks=[]}catch{tasks=[]}
$('#memo').value=localStorage.getItem(DRAFT)||'';
$('#date').textContent=new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric'}).format(new Date()).toUpperCase();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(tasks));$('#saveState').textContent=user?'同期中…':'この端末に保存'}catch{toast('端末の保存容量が不足しています')}}
async function api(path,opts={}){if(!user||!config.apiBase)throw Error('GoogleログインとAPI設定が必要です');const token=await user.getIdToken();const r=await fetch(config.apiBase+path,{...opts,headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`,...opts.headers}});if(!r.ok)throw Error(r.status===401?'再ログインしてください':'同期できませんでした');return r.status===204?null:r.json()}
async function syncTask(task){if(!user)return;try{await api('/api/tasks/'+task.id,{method:'PUT',body:JSON.stringify(task)});$('#saveState').textContent='同期済み'}catch{toast('端末に保存済み・同期は未完了');$('#saveState').textContent='同期未完了'}}
function render(){const counts={all:tasks.filter(t=>!t.deleted).length};for(const s of states)counts[s]=tasks.filter(t=>!t.deleted&&t.status===s).length;document.querySelectorAll('[data-filter]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.filter===filter));b.querySelector('span').textContent=counts[b.dataset.filter]});$('#sideCount').textContent=counts.todo+counts.doing;$('#totalCount').textContent=counts.all+' tasks';$('#listLabel').textContent=filter==='all'?'すべてのタスク':labels[filter];let list=tasks.filter(t=>!t.deleted&&(filter==='all'||filter===t.status)&&t.text.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(reverse?1:-1)*(a.createdAt-b.createdAt));$('#tasks').replaceChildren();$('#empty').hidden=!!list.length;$('#emptyText').textContent=query?'一致するタスクはありません':counts.all?'タスクはありません':'最初のメモを追加';list.forEach((t,i)=>{const shell=document.createElement('div');shell.className='task-shell';shell.style.animationDelay=Math.min(i*25,150)+'ms';shell.innerHTML='<div class="swipe-back" aria-hidden="true"><span>→</span><span>←</span></div><article class="task"><button class="status-button"></button><button class="task-body"><span class="task-title"></span><span class="task-meta"><span class="status-tag"></span><span class="task-date"></span></span></button><button class="task-menu" aria-label="タスクを編集">···</button></article>';const card=shell.querySelector('.task');card.classList.add(t.status);shell.querySelector('.task-title').textContent=t.text;shell.querySelector('.status-tag').textContent=labels[t.status];shell.querySelector('.task-date').textContent=new Intl.DateTimeFormat('ja-JP',{month:'numeric',day:'numeric'}).format(t.createdAt);const check=shell.querySelector('.status-button');check.textContent=t.status==='done'?'✓':t.status==='doing'?'·':'';check.ariaLabel=labels[t.status]+'：次のステータスへ';check.onclick=()=>move(t,1);shell.querySelector('.task-body').onclick=()=>edit(t);shell.querySelector('.task-menu').onclick=()=>edit(t);let start=null,dx=0,dy=0,swiped=false;card.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY};dx=dy=0;swiped=false});card.addEventListener('pointermove',e=>{if(!start)return;dx=e.clientX-start.x;dy=e.clientY-start.y;if(Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)*1.3){card.classList.add('dragging');card.style.transform=`translateX(${Math.max(-120,Math.min(120,dx))}px)`;swiped=true}});const end=()=>{if(!start)return;start=null;card.classList.remove('dragging');card.style.transform='';if(swiped&&Math.abs(dx)>68&&Math.abs(dx)>Math.abs(dy)*1.3)move(t,dx>0?1:-1);if(swiped)setTimeout(()=>swiped=false,0)};card.addEventListener('pointerup',end);card.addEventListener('pointercancel',()=>{start=null;card.style.transform='';card.classList.remove('dragging')});card.addEventListener('pointerleave',end);card.addEventListener('click',e=>{if(swiped){e.preventDefault();e.stopImmediatePropagation()}},true);$('#tasks').append(shell)})}
function move(t,dir){const next=Math.max(0,Math.min(2,states.indexOf(t.status)+dir));if(states[next]===t.status){toast(next===2?'完了済みです':'未着手です');return}t.status=states[next];t.updatedAt=Date.now();save();render();syncTask(t);navigator.vibrate?.(8)}
function add(text){const t={id:(crypto.randomUUID?.() || Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('')),text:text.trim(),status:'todo',createdAt:Date.now(),updatedAt:Date.now(),deleted:false};if(!t.text||t.text.length>4000)return false;tasks.unshift(t);save();syncTask(t);render();return true}
$('#composer').onsubmit=e=>{e.preventDefault();if(add($('#memo').value)){$('#memo').value='';localStorage.removeItem(DRAFT);$('#memo').focus()}};$('#memo').oninput=()=>{try{localStorage.setItem(DRAFT,$('#memo').value)}catch{toast('下書きを保存できませんでした')}};$('#memo').onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter')$('#composer').requestSubmit()};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#home').onclick=()=>{filter='all';render();$('#memo').focus()};$('#sideDone').onclick=()=>{filter='done';render()};$('#sort').onclick=()=>{reverse=!reverse;render();toast(reverse?'古い順':'新しい順')};$('#searchButton').onclick=()=>{$('#searchWrap').hidden=false;$('#search').focus()};$('#closeSearch').onclick=()=>{$('#searchWrap').hidden=true;query='';$('#search').value='';render()};$('#search').oninput=e=>{query=e.target.value;render()};
function edit(t){editId=t.id;$('#editText').value=t.text;$('#editDialog').showModal()}$('#cancelEdit').onclick=()=>$('#editDialog').close();$('#editForm').onsubmit=e=>{e.preventDefault();const t=tasks.find(t=>t.id===editId),text=$('#editText').value.trim();if(!text)return;t.text=text;t.updatedAt=Date.now();save();render();syncTask(t);$('#editDialog').close()};$('#deleteTask').onclick=()=>{const t=tasks.find(t=>t.id===editId);t.deleted=true;t.updatedAt=Date.now();save();render();syncTask(t);$('#editDialog').close();toast('削除しました')};
function settings(){$('#settings').showModal()}$('#account').onclick=settings;$('#settingsSide').onclick=settings;
$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(tasks.filter(t=>!t.deleted),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='shiro-tasks.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#aiButton').onclick=async()=>{const text=$('#memo').value.trim();if(!text){$('#memo').focus();return}if(!user){settings();return}const b=$('#aiButton');b.disabled=true;try{const r=await api('/api/organize',{method:'POST',body:JSON.stringify({text})});if(!Array.isArray(r.tasks)||!r.tasks.length)throw Error();for(const title of r.tasks)if(typeof title==='string')add(title);$('#memo').value='';localStorage.removeItem(DRAFT);toast('タスクに整理しました')}catch{toast('AIで整理できませんでした。メモは保存されています')}finally{b.disabled=false}};
async function initAuth(){if(!config.firebase||!config.apiBase){$('#authNotice').textContent='Google認証・クラウド同期・AIは接続設定待ちです。メモはこの端末で使えます。';$('#googleLogin').onclick=()=>toast('Google認証の接続設定が必要です');return}try{const app=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-app.js');firebase=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-auth.js');auth=firebase.getAuth(app.initializeApp(config.firebase));$('#googleLogin').onclick=async()=>{try{if(user){await firebase.signOut(auth);return}await firebase.signInWithPopup(auth,new firebase.GoogleAuthProvider())}catch{toast('ログインを完了できませんでした')}};firebase.onAuthStateChanged(auth,async u=>{user=u;$('#accountInfo').textContent=u?u.email:'この端末に保存中';$('#googleLogin').textContent=u?'ログアウト':'G　Googleでログイン';$('#authNotice').textContent='';if(!u){tasks=JSON.parse(localStorage.getItem(KEY)||'[]');render();return}$('#account').textContent=(u.displayName||'G').slice(0,1);const guest=tasks;const userKey=KEY+'.'+u.uid;tasks=JSON.parse(localStorage.getItem(userKey)||'[]');try{const remote=await api('/api/tasks');const merged=new Map(tasks.map(t=>[t.id,t]));for(const t of remote.tasks){const old=merged.get(t.id);if(!old||t.updatedAt>old.updatedAt)merged.set(t.id,t)}tasks=[...merged.values()];localStorage.setItem(userKey,JSON.stringify(tasks));render();$('#saveState').textContent='同期済み'}catch{toast('クラウドに接続できません');render()}/* Guest notes stay isolated until user explicitly exports/imports. */});}catch{toast('認証を読み込めませんでした')}}
// Persist signed-in changes separately to avoid exposing another account's notes.
const guestSave=save;save=function(){if(!user)return guestSave();try{localStorage.setItem(KEY+'.'+user.uid,JSON.stringify(tasks));$('#saveState').textContent='同期中…'}catch{toast('端末に保存できませんでした')}};
render();requestAnimationFrame(()=>requestAnimationFrame(()=>{$('#skeleton').style.opacity='0';setTimeout(()=>$('#skeleton').remove(),220)}));initAuth();
window.addEventListener('online',async()=>{if(user)for(const t of tasks)await syncTask(t)});
